export const FONT_STYLES: FontStyle[] = RAW.map(([family, style, postScriptName, url]) => ({ family, style, postScriptName, url }));

export const FONT_FAMILIES = Object.values(
  FONT_STYLES.reduce<Record<string, { family: string; styles: FontStyle[] }>>((acc, font) => {
    (acc[font.family] ??= { family: font.family, styles: [] }).styles.push(font);
    return acc;
  }, {}),
);

export const fontByPostScript = (name: string) => FONT_STYLES.find(f => f.postScriptName === name);
